package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.articles.JdbcSourceMemberEvidence;
import com.lianxibu.site.service.articles.SourceMemberEvidenceServiceTest;
import java.time.*;
import java.sql.Timestamp;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** Committed native rows only. Observation is not qualification or a writer permit. */
class SourceMemberObservedRowsTest {
    GenerationJdbcStoreTest db;JdbcSourceMemberEvidence store;
    GenerationJdbcStoreTest database(){return new GenerationJdbcStoreTest();}
    void setup(){db=database();db.fixture();db.jdbc.execute("DROP TABLE IF EXISTS source_run_items");db.jdbc.execute("DROP TABLE IF EXISTS source_runs");String text=db.source instanceof org.h2.jdbcx.JdbcDataSource?"CLOB":"LONGTEXT",time=db.source instanceof org.h2.jdbcx.JdbcDataSource?"TIMESTAMP(6)":"DATETIME(6)";db.jdbc.execute("CREATE TABLE source_runs(id VARCHAR(64) PRIMARY KEY,source_id VARCHAR(80),activation_stage VARCHAR(16),delivery_state VARCHAR(24),finished_at "+time+",config_version BIGINT,config_snapshot_json "+text+")");db.jdbc.execute("CREATE TABLE source_run_items(id VARCHAR(64) PRIMARY KEY,run_id VARCHAR(64),source_id VARCHAR(80),revision BIGINT,category VARCHAR(16),created_at "+time+",terminal_state VARCHAR(16),state VARCHAR(32),projection_decision VARCHAR(16),effective_valid INT,evidence_json "+text+",evidence_hash BINARY(32))");db.jdbc.update("INSERT INTO source_runs VALUES('fictional-run','fictional-source','production','complete',?,1,?)",Timestamp.from(Instant.parse("2026-01-01T20:00:00Z")),"{\"parser_version\":\"fictional-parser-v1\"}");db.jdbc.update("INSERT INTO source_run_items VALUES('fictional-item','fictional-run','fictional-source',2,'news_tech',?,'accepted','pending','initialized',1,?,?)",Timestamp.from(Instant.parse("2026-01-01T19:00:00Z")),SourceMemberEvidenceServiceTest.PAYLOAD,new byte[32]);store=new JdbcSourceMemberEvidence(db.source);}
    <T>T read(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(db.source));tx.setReadOnly(true);return tx.execute(s->work.get());}
    @Test void OriginalJoinAndAllFieldsMatchWriterAndActualChangesAreReadAgain(){setup();var observed=read(()->store.observed("fictional-item"));var locked=new TransactionTemplate(new DataSourceTransactionManager(db.source)).execute(s->store.lock("fictional-item"));assertNotNull(observed);assertEquals(locked.id(),observed.id());assertEquals(locked.runId(),observed.runId());assertEquals(locked.runIdentity(),observed.runIdentity());assertEquals(locked.sourceId(),observed.sourceId());assertEquals(locked.runSource(),observed.runSource());assertEquals(locked.revision(),observed.revision());assertEquals(locked.category(),observed.category());assertEquals(locked.createdAt(),observed.createdAt());assertEquals(locked.terminal(),observed.terminal());assertEquals(locked.state(),observed.state());assertEquals(locked.projection(),observed.projection());assertEquals(locked.valid(),observed.valid());assertEquals(locked.payload(),observed.payload());assertArrayEquals(locked.hash(),observed.hash());assertEquals(locked.activation(),observed.activation());assertEquals(locked.delivery(),observed.delivery());assertEquals(locked.finishedAt(),observed.finishedAt());assertEquals(locked.configVersion(),observed.configVersion());assertEquals(locked.config(),observed.config());db.jdbc.update("UPDATE source_run_items SET revision=revision+1 WHERE id='fictional-item'");assertEquals(3,read(()->store.observed("fictional-item")).revision());assertEquals(0,db.count("1=1"));}
    @Test void TransactionsIdentifiersMissingAndPhysicalLengthBoundsAreClosed(){setup();assertThrows(RuntimeException.class,()->store.observed("fictional-item"));assertThrows(RuntimeException.class,()->new TransactionTemplate(new DataSourceTransactionManager(db.source)).execute(s->store.observed("fictional-item")));assertThrows(RuntimeException.class,()->read(()->store.lock("fictional-item")));assertNull(read(()->store.observed("fictional-missing")));for(String id:new String[]{"","x".repeat(65),"bad\nroot"})assertThrows(RuntimeException.class,()->read(()->store.observed(id)));db.jdbc.update("UPDATE source_run_items SET evidence_json=?","x".repeat(262145));assertThrows(RuntimeException.class,()->read(()->store.observed("fictional-item")));db.jdbc.update("UPDATE source_run_items SET evidence_json=?",SourceMemberEvidenceServiceTest.PAYLOAD);db.jdbc.update("UPDATE source_runs SET config_snapshot_json=?","x".repeat(65537));assertThrows(RuntimeException.class,()->read(()->store.observed("fictional-item")));assertEquals(0,db.count("1=1"));}
    @Test void ObservationDoesNotWaitForWriterRowLockAndSeesOnlyCommittedVersion()throws Exception{setup();var held=new CountDownLatch(1);var release=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var writer=pool.submit(()->new TransactionTemplate(new DataSourceTransactionManager(db.source)).execute(s->{store.lock("fictional-item");db.jdbc.update("UPDATE source_run_items SET revision=3 WHERE id='fictional-item'");held.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("fictional native commit barrier");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new AssertionError(e);}return true;}));try{assertTrue(held.await(3,TimeUnit.SECONDS));var observed=pool.submit(()->read(()->store.observed("fictional-item")));assertEquals(2,observed.get(1,TimeUnit.SECONDS).revision());}finally{release.countDown();}assertTrue(writer.get(3,TimeUnit.SECONDS));assertEquals(3,read(()->store.observed("fictional-item")).revision());}assertEquals(0,db.count("1=1"));}
}
